export function clampElevation(a,t){return Math.min(t.elevationMax,Math.max(t.elevationMin,a))}export function dragView(a,t,e,n){return{azimuth:a.azimuth-t*n.dragSpeed,elevation:clampElevation(a.elevation+e*n.dragSpeed,n)}}export function stepView(a,t,e,n,{held:i=!1,reducedMotion:h=!1}={}){if(i)return{azimuth:a.azimuth,elevation:a.elevation,spin:t};const o=Math.exp(-n.glide*e),l={azimuth:t.azimuth*o,elevation:t.elevation*o},r=h?0:n.drift;return{azimuth:a.azimuth+(l.azimuth+r)*e,elevation:clampElevation(a.elevation+l.elevation*e,n),spin:l}}export function fitDistance(a,t,e,n){const i=Math.tan(t.fov*Math.PI/180/2),h=e*t.fitMargin/(i*a),o=e*Math.abs(Math.sin(n))*t.fitMargin/i;return Math.max(t.distance,h,o)}export function cameraPosition(a,t,e){const n=e*Math.cos(t);return{x:n*Math.cos(a),y:e*Math.sin(t),z:n*Math.sin(a)}}
